Not a deliverable. Prints per-state models and the unit-level differences between
merged and decided, so hand-written expectations can be eyeballed."""
import re, sys, os, json
sys.path.insert(0, os.path.dirname(__file__))
from gmerge import merge

FENCE = re.compile(r'^ {0,3}(`{3,}|~{3,})[ \t]*mermaid(-example)?\b', re.I)

def fences(text):
    lines = text.split('\n'); out = []; i = 0
    while i < len(lines):
        m = FENCE.match(lines[i])
        if m:
            ch, n = m.group(1)[0], len(m.group(1)); body = []; i += 1
            while i < len(lines) and not re.fullmatch(re.escape(ch) + '{%d,}[ \t]*' % n, lines[i]):
                body.append(lines[i]); i += 1
            out.append('\n'.join(body))
        i += 1
    return out

SHAPES = [('([', '])', 'stadium'), ('[(', ')]', 'cylinder'), ('[[', ']]', 'subroutine'),
          ('(((', ')))', 'doublecircle'), ('((', '))', 'circle'), ('{{', '}}', 'hexagon'),
          ('[/', '/]', 'lean_right'), ('[\\', '\\]', 'lean_left'), ('[/', '\\]', 'trapezoid'),
          ('[\\', '/]', 'inv_trapezoid'), ('[', ']', 'square'), ('(', ')', 'round'),
          ('{', '}', 'diamond'), ('>', ']', 'odd')]
LINK = re.compile(r'\s*(?:(\w+)@)?(<?)(-{2,}|-\.+-|={2,}|~{3,})(>|o|x)?(?:\|([^|]*)\|)?\s*')
LINK_TXT = re.compile(r'\s*(?:(\w+)@)?--\s+([^-][^>]*?)\s+(-->|---)\s*')
ID = re.compile(r'[A-Za-z_][\w-]*')

def parse_node(s, i):
    m = ID.match(s, i)
    if not m: raise ValueError('id expected at %r' % s[i:])
    nid = m.group(); i = m.end(); text = shape = None
    for o, c, nm in SHAPES:
        if s.startswith(o, i):
            j = s.find(c, i + len(o))
            if j < 0: continue
            text = s[i + len(o):j].strip()
            if text.startswith('"') and text.endswith('"'): text = text[1:-1]
            shape = nm; i = j + len(c); break
    cls = []
    while s.startswith(':::', i):
        m2 = ID.match(s, i + 3); cls.append(m2.group()); i = m2.end()
    return (nid, text, shape, cls), i

def kind_of(m):
    lt, line, head = m
    if line.startswith('~'): ln = 'invisible'
    elif line.startswith('='): ln = 'thick'
    elif '.' in line: ln = 'dotted'
    else: ln = 'solid'
    h = {'>': 'arrow', 'o': 'circle', 'x': 'cross', None: 'none', '': 'none'}[head]
    return '%s/%s/%s' % ('arrow' if lt else 'none', ln, h)

class M:
    def __init__(s):
        s.v = {}; s.order = []; s.nodestmt = set(); s.edges = []; s.subs = []; s.stack = []
        s.classdefs = {}; s.linkstyles = {}; s.edge_ids = set(); s.dropped = []
    def vert(s, nid, text=None, shape=None, cls=(), styles=(), stmt=False):
        if nid in s.edge_ids and stmt:
            s.dropped.append(nid); return
        if nid not in s.v:
            s.v[nid] = dict(text=nid, shape='none', classes=[], styles=[], link=None); s.order.append(nid)
        d = s.v[nid]
        if text is not None: d['text'] = text
        if shape is not None: d['shape'] = shape
        d['classes'] += list(cls); d['styles'] += list(styles)
        if stmt: s.nodestmt.add(nid)
        for sg in s.stack: sg['nodes'].append(nid)

def parse(text):
    m = M(); lines = text.split('\n'); i = 0
    while i < len(lines) and (not lines[i].strip() or lines[i].strip().startswith('%%')): i += 1
    hdr = lines[i].strip()
    if not re.match(r'(flowchart|flowchart-elk|graph)(\s|$)', hdr): raise ValueError('not flowchart')
    for raw in lines[i + 1:]:
        st = raw.strip()
        if not st or st.startswith('%%'): continue
        if st == 'end':
            sg = m.stack.pop(); m.subs.append(sg)
            if m.stack: m.stack[-1]['nodes'].append(sg['key'])
            continue
        if st.startswith('subgraph '):
            h = st[9:].strip(); mm = re.fullmatch(r'([\w-]+)\s*\[(.*)\]', h)
            if mm: key, title = mm.group(1), mm.group(2).strip().strip('"')
            elif re.fullmatch(r'[\w-]+', h): key, title = h, h
            else: title = h.strip('"'); key = 'title:' + title
