            links.append((ml.group(1), (ml.group(2), ml.group(3), ml.group(4)), ml.group(5) or ''))
            pos = ml.end()
        for gi, grp in enumerate(groups):
            for (nid, t, sh, cl) in grp:
                m.vert(nid, t, sh, cl, stmt=(sh is not None))
            if gi > 0:
                eid, k, lab = links[gi - 1]
                for a in groups[gi - 1]:
                    for b in grp:
                        e = dict(start=a[0], end=b[0], kind=kind_of(k), text=lab.strip(), id=None)
                        if eid and eid not in m.edge_ids:
                            e['id'] = eid; m.edge_ids.add(eid)
                        m.edges.append(e)
    return m

def model(text, stratum):
    if stratum == 'D':
        fs = fences(text)
        if len(fs) != 1: return 'G0:%d fences' % len(fs)
        text = fs[0]
    m = parse(text)
    sub_keys = {sg['key'] for sg in m.subs}
    kinds = {}
    for n in m.order:
        if n in sub_keys and n not in m.nodestmt: continue
        kinds.setdefault(n, set()).add('node')
    for k in sub_keys: kinds.setdefault(k, set()).add('subgraph')
    for e in m.edges:
        if e['id']: kinds.setdefault(e['id'], set()).add('edge')
    U = {}
    for k, ks in kinds.items(): U[('kind', k)] = '+'.join(sorted(ks))
    for n in m.order:
        if 'node' not in kinds.get(n, ()): continue
        d = m.v[n]
        U[('text', n)] = d['text']; U[('shape', n)] = d['shape']
        U[('styles', n)] = tuple(d['styles']); U[('link', n)] = d['link']
        for c in d['classes']: U[('class', n, c)] = True
    for sg in m.subs: U[('title', sg['key'])] = sg['title']
    hold = {}
    for sg in m.subs:
        for x in sg['nodes']:
            hold.setdefault(x, sg['key'])
    for x in list(kinds):
        U[('holder', x)] = hold.get(x)
    cnt = {}
    for idx, e in enumerate(m.edges):
        key = ('edge', e['id']) if e['id'] else ('edge', e['start'], e['end'], e['kind'], e['text'])
        cnt[key] = cnt.get(key, 0) + 1
        if e['id']: U[('ends', e['id'])] = (e['start'], e['end'], e['kind'], e['text'])
        if idx in m.linkstyles: U[('linkstyle',) + key[1:]] = m.linkstyles[idx]
    for k, c in cnt.items(): U[k] = c
    for c, v in m.classdefs.items(): U[('classDef', c)] = tuple(v)
    U[('__order',)] = tuple(n for n in m.order if 'node' in kinds.get(n, ()))
    U[('__dropped',)] = tuple(m.dropped)
    return U

def report(fx):
    stratum = 'D' if os.path.exists(os.path.join(fx, 'base.md')) else 'F'
    ext = 'md' if stratum == 'D' else 'mmd'
    S = {}
    for nm in ('base', 'o', 't'):
        S[nm] = model(open(os.path.join(fx, nm + '.' + ext)).read(), stratum)
    conflict, merged = merge(fx)
    print('#' * 10, os.path.basename(fx.rstrip('/')), stratum, 'CONFLICT' if conflict else 'CLEAN')
    if conflict: return
    try:
        Mg = model(merged, stratum)
    except Exception as ex:
        print('  merged does not parse in mini:', ex); return
    if isinstance(Mg, str): print('  ', Mg); return
    B, O, T = S['base'], S['o'], S['t']
    keys = set(B) | set(O) | set(T) | set(Mg)
    for k in sorted(keys, key=repr):
        if k[0].startswith('__'): continue
        b, o, t, g = B.get(k), O.get(k), T.get(k), Mg.get(k)
        if o == t: dec, st = o, 'decided'
        elif o == b: dec, st = t, 'decided'
        elif t == b: dec, st = o, 'decided'
        else: dec, st = None, 'CONFLICT'
        if st == 'CONFLICT':
            print('  MODEL CONFLICT %r: B=%r O=%r T=%r merged=%r' % (k, b, o, t, g))
        elif g != dec:
            print('  DIFF %r: decided=%r merged=%r   (B=%r O=%r T=%r)' % (k, dec, g, b, o, t))
    # pairwise vertex order
    def pos(U): return {n: i for i, n in enumerate(U[('__order',)])}
    pb, po, pt, pg = pos(B), pos(O), pos(T), pos(Mg)
    names = sorted(pg)
    for i, x in enumerate(names):
        for y in names[i + 1:]:
            def rel(p):
                return None if x not in p or y not in p else (p[x] < p[y])
            b, o, t, g = rel(pb), rel(po), rel(pt), rel(pg)
            if o == t: dec = o
            elif o == b: dec = t
            elif t == b: dec = o
            else: continue
            if dec is not None and g is not None and dec != g:
                print('  ORDER inversion (%s,%s): decided %s first' % (x, y, x if dec else y))
    if Mg[('__dropped',)]: print('  dropped node stmts:', Mg[('__dropped',)])

if __name__ == '__main__':
    for fx in sys.argv[1:]:
        try: report(fx)
        except Exception as ex: print('#' * 10, fx, 'ERROR', ex)

